For any monotone test function $f(\cdot)$ and $d \geq 2$, we have\footnote{For $d=1$, we directly have ${H(f)}=\frac{1}{\left(f(d)-f(0)\right)^2}$ by definition.}
\begin{align}

 \frac{1}{\left(f(d)-f(0)\right)^2} \leq {H(f)}\leq \frac {16}{\left(f(d)-f(0)\right)^2}\left(\log\log d +2\right)^2 d.  
\end{align}

The non-adaptive test design and decoding outlined in Section 3 has the following performance:
\begin{enumerate}[label=\alph*)]
  \item  
  The probability of error is at most $\varepsilon$; 

  \item  
  The number of tests $T$ satisfies
  \begin{align}


    T \leq 376017  {P_{min}({{q}^*})}  {H(f)} d\log \left( \frac{2n}{\varepsilon } \right)+1 \leq 376017 {H(f)} d\log\left( \frac{2n}{\varepsilon} \right)+1;
  \end{align}
  \item 
  The test design parameter ${{q}^*}$ in (15) can be efficiently approximated in ${\cal O}(d^7 \log^2(d))$ time; 
  \item  
  The computation complexity of decoding is ${\cal O} \left( n{H(f)} d  \log \left( \frac{n}{\varepsilon} \right) \right)$. 
\end{enumerate}

Suppose that the decoding rule used is (16). Then we show that the probability of error is at most $ \varepsilon$ 
if 
\begin{equation} 

{T} \ge {\Gamma}_1({q}) := \frac{13}{6{q}} {m}.
\end{equation}

\begin{equation} 
    i =
    \left\{
    \begin{array}{ll}
    \text{non-defective} & \text{if} \; \frac{{{m}_{i}^+}}{{{m}_{i}}} \le \frac{{P(-,{q})}+{P(+,{q})}}{2}, \\
    \text{defective}     & \text{if} \; \frac{{{m}_{i}^+}}{{{m}_{i}}} > \frac{{P(-,{q})}+{P(+,{q})}}{2}.
    \end{array}
    \right.
\end{equation}}

Suppose that the decoding rule used is (17). Then we show that the probability of error is at most $ \varepsilon$ 
if 
\begin{equation} 

T \ge {\Gamma}_2({q}) := \frac{13}{6(1-{q})} {s} . 
\end{equation}

\begin{equation} 
    i =
    \left\{
    \begin{array}{ll}
    \text{non-defective} & \text{if} \; \frac{{{s}_{i}^+}}{{{s}_{i}}} > \frac{{Q(-,{q})}+{Q(+,{q})}}{2}, \\
    \text{defective}     & \text{if} \; \frac{{{s}_{i}^+}}{{{s}_{i}}} \le \frac{{Q(-,{q})}+{Q(+,{q})}}{2}.
    \end{array}
    \right.
\end{equation}}

There exists some ${q}_0\in(0,1)$ such that
\begin{equation} 

{\hat{\Gamma}} ({q}_0) \leq 376017 {H(f)} d\log \left( \frac{2n}{\varepsilon } \right),
\end{equation} 
where ${H(f)}$ is the ``sensitivity parameter" defined in (18).

Let $d\geq 3$. For any ${L}',{U}' \in \{1 ,\dots, d-1\}$ with ${L}' < {U}'$ and $f({L}')<f({U}')$, there exists ${q}_0 \in \left(\frac {{L}'} {d}, \frac {{U}'} {d}\right)$ such that ${\hat{\Gamma}} ({q}_0)$ in (14) satisfies

\begin{equation}

{\hat{\Gamma}} ({q}_0) \leq  31334.75 \times \frac{1}{{\alpha}^2} \left( \frac{{U}'-{L}'}{f({U}')-f({L}')} \right)^2  d\log \left( \frac{2n}{\varepsilon } \right)
\end{equation} 
where ${\alpha} := \frac{1}{2} \min\left\{{U}'-{L}',\sqrt{{L}'},\sqrt{d-{U}'}\right\}$.

\begin{enumerate}
  \item  By choosing ${q}_0 = \frac {1} {d+1}$, which implicitly requires $f(1) - f(0)  > 0$,\footnote{If $f(1) - f(0) =0 $ or $f(d) - f(d-1) =0$, we can  choose ${q}_0$ as in Proposition 5.} ${\hat{\Gamma}} ({q}_0)$ in (14) satisfies 

\begin{equation} 

    {\hat{\Gamma}} ({q}_0) \le \frac{266.45}{(f(1) - f(0))^2} d \log \left( \frac{2n}{\varepsilon} \right).
\end{equation}
\item  By choosing ${q}_0 =\frac {d} {d+1}$, which implicitly requires $f(d) - f(d-1) > 0$,$^{fn:boundary:cases}$ ${\hat{\Gamma}} ({q}_0)$ in (14) satisfies  

\begin{equation} 

    {\hat{\Gamma}} ({q}_0) \leq \frac{266.45}{(f(d) - f(d-1))^2} d \log \left( \frac{2n}{\varepsilon} \right).
\end{equation}
\end{enumerate}

For all ${q}\in(0,1)$, we have
\begin{align}

    f(d)\ge  {P(+,{q})} > {P(-,{q})} = {Q(-,{q})} > {Q(+,{q})} \ge f(0),
\end{align}
\begin{align}

    {\nabla({q})} = \frac{{q}}{1-{q}} {\Delta({q})},
\end{align}
\begin{align}

    1\geq {P_{\min}({q})} \geq \max \left\{{\Delta({q})}, {\nabla({q})}\right\}.
\end{align}

Let $d\geq 3$. For any ${L}',{U}' \in \{1 ,\dots, d-1\}$ with ${L}' < {U}'$ and $f({L}')<f({U}')$, there exists ${q}_0 \in \left(\frac {{L}'} {d}, \frac {{U}'} {d}\right)$ such that ${\hat{\Gamma}} ({q}_0) $ defined in (14) satisfies 
\begin{equation} 

{\hat{\Gamma}} ({q}_0)  \leq 1253.39 \times \frac{ (d-{L}') {U}' }{{\alpha}^2 (d-{U}'){L}'} \left( \frac{{U}'-{L}'}{f({U}')-f({L}')} \right)^2  d\log \left( \frac{2n}{\varepsilon } \right),
\end{equation} 

where ${\alpha} := \frac{1}{2} \min\left\{{U}'-{L}',\sqrt{{L}'},\sqrt{d-{U}'}\right\}$.

For any $j >  i  > 0$ and $d > j +  i  $, we have 
\begin{align} 
\int_{\frac {j}{d}}^{\frac {j+ i }{d}} {q}^j (1-{q})^{d-j} {\,\mathrm{d}} {q} &\geq \left( \frac{j}{d} \right)^j \left( \frac{d-j}{d} \right)^{d-j} \frac{j(d-j- i )}{ i  d^2} \left( 1 - \exp\left( \frac{-i ^2 d  }{j (d-j- i )} \right) \right),  \\ 
\int_{\frac {j- i }{d}}^{\frac {j}{d}} {q}^j (1-{q})^{d-j} {\,\mathrm{d}} {q} &\geq \left( \frac{j}{d} \right)^j \left( \frac{d-j}{d} \right)^{d-j} \frac{(j- i )(d-j)}{i d^2 } \left( 1 - \exp\left( \frac{- i ^2 d }{(j- i )(d-j)} \right) \right). 
\end{align}

Let ${L}',{U}' \in \{1, \dots, d-1\}$ with $d\geq 3$ and  ${L}' < {U}'$, we have that for all $j \in [{L}',{U}']$, 
\begin{equation*}
\int_{\frac {{L}'}{d}}^{\frac {{U}'}{d}} {q}^j (1-{q})^{d-j} {\,\mathrm{d}} {q} \ge \left(\frac{j}{d}\right)^j \left(\frac{d-j}{d}\right)^{d-j} \frac{{\alpha}}{2d},
\end{equation*}
where ${\alpha} := \frac{1}{2} \min\left\{{U}'-{L}' , \sqrt{{L}'} , \sqrt{d-{U}'}\right\}$.

For any $j=1,\dots,d-1$, we have
\begin{equation*}
\frac{\sqrt{2\pi}}{e^2} \sqrt{\frac{d}{j(d-j)}} \leq \binom{d}{j} \left( \frac{j}{d} \right)^j \left( \frac{d-j}{d} \right)^{d-j} \leq \frac{e}{\pi} \sqrt{\frac{d}{j(d-j)}}.
\end{equation*}

We have
\begin{equation}
    {{q}^*} \in \left( \frac{1}{376017d^3} , 1-\frac{1}{376017d^3}\right).
\end{equation}

For any ${\hat{{q}}^*} \in \left[ {{q}^*}-\frac{1}{376017d^4} , {{q}^*}+\frac{1}{376017d^4} \right]$, 
\begin{equation}
    {\Gamma({\hat{{q}}^*})} \le 64e^2 {\Gamma} ({{q}^*}).
\end{equation}

For any non-adaptive group testing algorithm that ensures a reconstruction error of at most $\varepsilon$, the number of tests $T$ must satisfy  
\begin{equation}

    T \geq \frac{1}{\log e} {h(f)} \left( (1-\varepsilon)\log\binom{n}{d} - 1 \right).
\end{equation}

